import json,html
from pathlib import Path
p=Path(__file__).parent;g=json.loads((p/'dag.json').read_text())
book='https://miguelhernan.org/s/hernanrobins_WhatIf_2jan25.pdf';trial='https://doi.org/10.1177/2332858416673968';ox='https://www.stats.ox.ac.uk/~evans/APTS/intro.html';wwc='https://ies.ed.gov/ncee/wwc/Study/86375'
def evidence(url,locator,claim):return {'url':url,'locator':locator,'claim':claim}
def node(id,q,a,e):return {'id':id,'question':q,'answer':a,'status':'supported','evidence':e}
g['revisions'].append({'round':1,'gaps':['Effect definition','Group selection','Random assignment','Trial conduct'],'searches':['Hernan Robins Causal Inference What If chapter 1 table 1.1 pdf','ASSISTments randomized trial 2769 students 43 schools PNAS 2016 online homework full text'],'evidence':[evidence(book,'§§1.1–1.5, 2.1, 3.1–3.2','Individual missing outcomes; randomization and observational assumptions'),evidence(ox,'§§1.1–1.3','Precisely specify the intervention comparison')],'changes':['Retained association and potential outcomes as separate prerequisites.','Detected that implementation question bundled nonuse, missingness, and random uncertainty; split these below.','Trial search corrected initial guessed venue/count to AERA Open and 2,850 students.']})
g['nodes']=[node('compare','What does a difference in group averages describe?','An association between group membership and observed scores.',[evidence(book,'§1.5, pp.10–12','Association compares observed groups.')]),node('counterfactual','What does it mean for the app to cause a score change?','Compare scores under defined app and no-app interventions for the same population; individual alternatives cannot both be observed.',[evidence(book,'§§1.1–1.2, pp.3–6','Potential outcomes define individual and average effects.'),evidence(ox,'§1.2','Specify population, intervention, comparison, outcome, time.')]),node('confounding','Why can users differ even without an app effect?','Preexisting causes of both participation and scores make group differences insufficient.',[evidence(book,'§3.1, pp.27–28','Treatment assignment may reflect underlying outcome risk.')]),node('random','How does random assignment support a causal comparison?','Assignment does not systematically select students according to potential scores, so the other group estimates the missing average in expectation.',[evidence(book,'§2.1, pp.13–16','Randomization produces exchangeability in expectation.')]),node('assignment','What effect is estimated when some assigned students do not use the app?','The assigned-group comparison estimates an offer or programme effect; comparing actual users can reintroduce selection.',[evidence(book,'§2.1 p.14 and §3.1 pp.27–28','Ideal treatment-effect identification requires adherence; observed treatment selection requires assumptions.')]),node('missing','Why do missing scores and shared learning matter?','Post-assignment selection or shared exposure can change the comparison; follow assigned participants and define the intervention.',[evidence(book,'Fine Point 1.1 p.5','Interference changes the definition of the causal effect.'),evidence(trial,'Data Linking and Student-Level Attrition; Analytic Models','Missing students and clustered assignment were addressed.'),evidence(wwc,'Review Details August 2026','Low attrition and nonresponse in reviewed trial.')]),node('uncertainty','Why does a randomized difference remain uncertain?','Finite assignment and sampling vary; uncertainty intervals quantify precision under assumptions and cannot correct confounding.',[evidence(book,'§1.4 pp.8–10; §10.1 pp.132–134; Fine Point 10.2 p.136','Random variability prevents certainty; confidence intervals require assumptions and do not capture systematic bias.')]),node('observational','What can be learned when random assignment is unavailable?','Measured adjustment requires comparable groups, well-defined interventions, and sufficient measured common causes.',[evidence(book,'§§3.1–3.2 pp.27–29','Consistency, exchangeability, positivity assumptions.')]),node('target','Why is the observed association insufficient, and how could we estimate whether the app helped?','Higher user scores can reflect selection; define a trial, randomize where feasible, preserve assignment, follow outcomes, quantify uncertainty, and limit conclusions to the intervention and population studied.',[evidence(book,'Chapters 1–3','Overall causal framework'),evidence(trial,'Research Design; Results; Discussion','A real education trial tests a specific app-plus-training package.')])]
g['edges']=[]
for a,b,why in [('compare','confounding','Need to understand the observed contrast before asking why it may be misleading.'),('counterfactual','confounding','Need an effect definition to distinguish effect from selection.'),('confounding','random','Need the selection problem to understand what random assignment resolves.'),('random','assignment','Need the assignment comparison before distinguishing it from actual use.'),('random','missing','Need the intended randomized comparison before examining post-assignment changes.'),('random','uncertainty','Need random assignment before interpreting chance imbalance.'),('confounding','observational','Adjustment is an attempted solution to common causes, not a generic correlation procedure.'),('counterfactual','target','The question needs a defined causal contrast.'),('assignment','target','The estimated effect must match the offered or used intervention.'),('missing','target','Observed results must preserve the intended comparison.'),('uncertainty','target','Causal conclusions require calibrated precision.'),('observational','target','The answer should explain the alternative when a trial cannot be run.')]:g['edges'].append({'from':a,'to':b,'why':why})
g['revisions'].append({'round':2,'gaps':['Concrete trial evidence','Subgroup exhibit accuracy','Asset access'],'searches':['ASSISTments full published methods and results','Linked 2017 corrigendum','WWC study 86375 current review'],'evidence':[evidence(trial,'Table 2 and Figure 2 p.9','Adjusted overall effect differs from unadjusted subgroup results.'),evidence('https://doi.org/10.1177/2332858417707489','Corrected Table 4','Corrected effect sizes 0.29 and 0.12; subgroup means unchanged.'),evidence(wwc,'August 2026 Findings','690.79 versus 681.95 adjusted means, 2,850 students.')],'changes':['Split implementation into assignment, missing, uncertainty.','Added observational alternative because randomized trials may not be feasible.','Extracted original figure from ERIC PDF after image CDN returned 403.','Omitted corrected effect-size column from report prose to avoid unnecessary statistical prerequisites; used corrected subgroup score differences.','No unsupported prerequisite nodes remain; actual unspecified app effect remains unknown by design.']})
ids={n['id'] for n in g['nodes']};assert len(ids)==len(g['nodes']);assert g['target_id'] in ids
adj={i:[] for i in ids}
for e in g['edges']:assert e['from'] in ids and e['to'] in ids;adj[e['from']].append(e['to'])
def visit(n,stack):
 assert n not in stack,'cycle'
 return n==g['target_id'] or any(visit(x,stack+[n]) for x in adj[n])
for n in ids:assert visit(n,[]),n
# Independently check all branches for cycles, not short-circuit reachability.
def cycles(n,stack):
 assert n not in stack
 for x in adj[n]:cycles(x,stack+[n])
for n in ids:cycles(n,[])
g['validation']={'unique_ids':True,'valid_endpoints':True,'acyclic':True,'all_nodes_reach_target':True,'node_count':len(ids),'edge_count':len(g['edges']),'semantic_review':'Each edge reviewed against report sequence; structural validity is not proof of prerequisite quality.'}
(p/'dag.json').write_text(json.dumps(g,indent=2))
positions={'compare':(30,30),'counterfactual':(390,30),'confounding':(210,150),'random':(30,270),'observational':(570,270),'assignment':(30,400),'missing':(300,400),'uncertainty':(570,400),'target':(300,570)}
labels={'compare':['Observed group','averages'],'counterfactual':['Define the causal','comparison'],'confounding':['Selection and','confounding'],'random':['Random','assignment'],'observational':['Nonrandom','alternatives'],'assignment':['Offer versus','actual use'],'missing':['Missing scores','and shared exposure'],'uncertainty':['Chance and','uncertainty'],'target':['Estimate whether','the app helped']}
svg='<svg xmlns="http://www.w3.org/2000/svg" width="860" height="690" viewBox="0 0 860 690"><title>Prerequisite graph for causal inference explanation</title><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#646c77"/></marker></defs><rect width="860" height="690" fill="#f5f4f0"/>'
for e in g['edges']:
 x,y=positions[e['from']];x2,y2=positions[e['to']];svg+=f'<path d="M{x+115},{y+65} L{x2+115},{y2}" fill="none" stroke="#646c77" marker-end="url(#arrow)"><title>{html.escape(e["why"])}</title></path>'
for n,(x,y) in positions.items():
 svg+=f'<g><rect x="{x}" y="{y}" width="230" height="65" fill="white" stroke="#cbd0d3"/>'
 for j,line in enumerate(labels[n]):svg+=f'<text x="{x+115}" y="{y+27+j*22}" text-anchor="middle" font-family="Arial" font-size="17" fill="#101527">{line}</text>'
 svg+='</g>'
svg=svg.replace('M505,95 L415,570', 'M505,95 L840,120 L840,550 L415,570');svg+='</svg>';(p/'dag.svg').write_text(svg)
(p/'dag.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explanation prerequisites</title><style>body{max-width:900px;margin:30px auto;padding:20px;font:17px/1.6 Arial;background:#f5f4f0;color:#101527}svg{width:100%;height:auto}li{margin:12px 0}</style><h1>Explanation prerequisites</h1><p>An arrow A → B means understanding B requires A. This is an explanation graph, not a causal graph of the app.</p>'+svg+'<h2>Dependency justifications</h2><ul>'+''.join('<li><strong>'+e['from']+' → '+e['to']+':</strong> '+html.escape(e['why'])+'</li>' for e in g['edges'])+'</ul></html>')
print(g['validation'])
